import { unstable_cacheTag as cacheTag } from "next/cache";
import { revalidateTag } from "next/cache";

interface Product {
  id: string;
  name: string;
  price: number;
  inventory: number;
  available: boolean;
  sku: string;
}

async function getProducts(): Promise<Product[]> {
  "use cache";
  cacheTag("products");

  // Simulated product fetch - in production this queries your ERP/PIM
  // This data is cached and won't re-query on every request
  const products: Product[] = [
    {
      id: "1",
      name: "Wireless Headphones",
      price: 99.99,
      inventory: 150,
      available: true,
      sku: "WH-001",
    },
    {
      id: "2",
      name: "Smart Watch",
      price: 249.99,
      inventory: 75,
      available: true,
      sku: "SW-002",
    },
    {
      id: "3",
      name: "USB-C Cable",
      price: 19.99,
      inventory: 500,
      available: true,
      sku: "CB-003",
    },
    {
      id: "4",
      name: "Laptop Stand",
      price: 59.99,
      inventory: 0,
      available: false,
      sku: "LS-004",
    },
  ];

  return products;
}

export default async function AdminCatalogPage() {
  const products = await getProducts();

  async function syncCatalog() {
    "use server";

    // Trigger background revalidation - doesn't block the user
    // The admin can continue working immediately while data refreshes
    revalidateTag("products");
  }

  return (
    <div className="container mx-auto px-4 py-8">
      <div className="flex items-center justify-between mb-8">
        <h1 className="text-3xl font-bold">Product Catalog</h1>
        <form action={syncCatalog}>
          <button
            type="submit"
            className="bg-blue-600 hover:bg-blue-700 text-white font-medium py-2 px-4 rounded transition-colors"
          >
            Sync latest catalog
          </button>
        </form>
      </div>

      <div className="bg-white rounded-lg shadow overflow-hidden">
        <table className="min-w-full">
          <thead className="bg-gray-50">
            <tr>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                SKU
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Name
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Price
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Inventory
              </th>
              <th className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">
                Status
              </th>
            </tr>
          </thead>
          <tbody className="bg-white divide-y divide-gray-200">
            {products.map((product) => (
              <tr key={product.id}>
                <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-gray-900">
                  {product.sku}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                  {product.name}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                  ${product.price.toFixed(2)}
                </td>
                <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-900">
                  {product.inventory}
                </td>
                <td className="px-6 py-4 whitespace-nowrap">
                  <span
                    className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${
                      product.available
                        ? "bg-green-100 text-green-800"
                        : "bg-red-100 text-red-800"
                    }`}
                  >
                    {product.available ? "Available" : "Out of Stock"}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <p className="mt-4 text-sm text-gray-500">
        Last updated: {new Date().toLocaleString()}
      </p>
    </div>
  );
}

